set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select public.gym_save_nutrition_preferences('{}',null,true);
select test.assert((select onboarding_status='skipped' and ai_consent=false and age is null from public.gym_nutrition_preferences where user_id=auth.uid()),'Skip retains optional privacy defaults');
select public.gym_save_nutrition_preferences('{"age":35,"height_cm":175,"weight_kg":80,"activity":"moderate","goal":"support_training","diet":"vegetarian","allergens":["milk"],"avoid_foods":["olives"],"usual_foods":"Rice bowls","cooking_minutes":20,"budget":"low","calorie_target":null,"ai_consent":false}',0,false);
select test.assert((select onboarding_status='completed' and revision=1 and diet='vegetarian' and usual_foods='Rice bowls' from public.gym_nutrition_preferences where user_id=auth.uid()),'Preferences persist with revision');
select test.assert_raises($$select public.gym_save_nutrition_preferences('{}',0,true)$$,'Nutrition preferences changed');
select test.assert_raises($$update public.gym_nutrition_preferences set age=17 where user_id=auth.uid()$$,'violates check');
select test.assert_raises($$update public.gym_nutrition_preferences set calorie_target=500 where user_id=auth.uid()$$,'violates check');
select test.assert_raises($$update public.gym_nutrition_preferences set allergens=array['invalid'] where user_id=auth.uid()$$,'violates check');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
select test.assert((select count(*)=0 from public.gym_nutrition_preferences),'Other nutrition profile is private');
update public.gym_nutrition_preferences set usual_foods='Changed' where user_id='00000000-0000-0000-0000-000000000001';
select test.assert_raises($$insert into public.gym_nutrition_preferences(user_id)values('00000000-0000-0000-0000-000000000001')$$,'row-level security');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select test.assert((select usual_foods='Rice bowls' from public.gym_nutrition_preferences),'Another user cannot overwrite preferences');
reset role;
set role anon;
select test.assert_raises('select * from public.gym_nutrition_preferences','permission denied');
select test.assert_raises($$select public.gym_save_nutrition_preferences('{}',null,true)$$,'permission denied');
reset role;
